16	/** A claim a person on a sheet makes: an amount (two decimals), a date, a note and a status (DRAFT
17	 *  when added). A claim with a negative amount is a correction, naming the number of the SETTLED
18	 *  claim of the same person it corrects. */
19	@Entity
20	@Table(name = "claim")
21	public class Claim {
22	
23	    @Id
24	    @GeneratedValue(strategy = GenerationType.IDENTITY)
25	    private Long id;
26	
27	    @Column(name = "sheet_id", nullable = false)
28	    private String sheetId;
29	
30	    @Column(name = "person_id", nullable = false)
31	    private Long personId;
32	
33	    /** When the claim was listed under its person, from the database's sequence: when it was added,
34	     *  or last reassigned. Claims are listed newest first by it; set by the database only. */
35	    @Column(name = "listed", insertable = false, updatable = false)
36	    private Long listed;
