55	
56	    /** The claim's number, given when it is opened and kept when it is voided (never reused): the
57	     *  sheet-wide number (1, 2, ...), or under period numbering <period>-<n> or X-<n>; null for a
58	     *  claim never opened. */
59	    @Column(name = "claim_number")
60	    private String number;
61	
62	    /** The due fixed when the claim was settled; null until then, or when its grade had no rate. */
63	    @Column(name = "settled_due", precision = 12, scale = 2)
64	    private BigDecimal settledDue;
65	
66	    /** The user who opened the claim; null for a claim never opened. */
67	    @Column(name = "opened_by")
68	    private String openedBy;
69	
70	    /** Whether the person's last statement bound the claim to the figure it had then. */
71	    @Column(name = "stated", nullable = false)
72	    private boolean stated;
73	
