75	    @Column(name = "stated_due", precision = 12, scale = 2)
76	    private BigDecimal statedDue;
77	
78	    /** The number of the claim this correction corrects; null for a claim that is not a correction. */
79	    @Column(name = "corrects_number")
80	    private String corrects;
81	
82	    protected Claim() {
83	    }
84	
85	    public Claim(String sheetId, Long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note,
86	            String corrects) {
