119	    }
120	
121	    public String getCorrects() {
122	        return corrects;
123	    }
124	
125	    public void setCorrects(String corrects) {
126	        this.corrects = corrects;
127	    }
128	
129	    /** Whether the claim is a correction: its amount is negative. */
130	    public boolean isCorrection() {
131	        return amount.signum() < 0;
132	    }
133	
134	    public LocalDate getDate() {
135	        return date;
136	    }
137	
138	    public void setDate(LocalDate date) {
139	        this.date = date;
140	    }
141	
142	    public LocalDate getDueBy() {
143	        return dueBy;
144	    }
145	
146	    public String getNote() {
147	        return note;
148	    }
149	
150	    public void setNote(String note) {
151	        this.note = note;
152	    }
153	
154	    public ClaimStatus getStatus() {
155	        return status;
156	    }
157	
158	    public void setStatus(ClaimStatus status) {
159	        this.status = status;
160	    }
161	
162	    public String getNumber() {
163	        return number;
164	    }
165	
166	    public void setNumber(String number) {
167	        this.number = number;
168	    }
169	
170	    public BigDecimal getSettledDue() {
171	        return settledDue;
172	    }
173	
174	    public void setSettledDue(BigDecimal settledDue) {
175	        this.settledDue = settledDue;
176	    }
177	
178	    public String getOpenedBy() {
