211	    /** Whether the claim is held: it is OPEN and dated within one of its person's holds. */
212	    public boolean heldBy(List<PersonHold> holds) {
213	        return status == ClaimStatus.OPEN && holds.stream().anyMatch(hold -> hold.contains(date));
214	    }
215	
216	    /** Whether the claim counts in live totals given its person's holds: one that counts, unless it
217	     *  is held and not bound by a statement (a bound claim stays in whatever its date). */
218	    public boolean countsLive(List<PersonHold> holds) {
219	        return counts() && (stated || !heldBy(holds));
220	    }
