222	package net.officefloor.hq.app.claim;
223	
224	import java.math.BigDecimal;
225	import java.math.RoundingMode;
226	import java.time.LocalDate;
227	import java.time.temporal.ChronoUnit;
228	import java.util.List;
229	import java.util.Map;
230	import java.util.stream.Collectors;
231	import java.util.NoSuchElementException;
232	import net.officefloor.hq.app.Audit;
233	import net.officefloor.hq.app.person.Person;
234	import net.officefloor.hq.app.period.Period;
235	import net.officefloor.hq.app.period.PeriodClosedException;
236	import net.officefloor.hq.app.period.PeriodRepository;
237	import net.officefloor.hq.app.person.PersonGradeService;
238	import net.officefloor.hq.app.person.PersonRepository;
239	import net.officefloor.hq.app.person.PersonRetiredException;
240	import net.officefloor.hq.app.rate.Rate;
241	import net.officefloor.hq.app.rate.RateService;
242	import net.officefloor.hq.app.setting.Role;
243	import net.officefloor.hq.app.setting.SettingService;
244	import net.officefloor.hq.app.sheet.SheetService;
245	import org.springframework.stereotype.Service;
246	import org.springframework.transaction.annotation.Transactional;
247	
248	/** The claims people on a sheet make. */
249	@Service
250	public class ClaimService {
251	
252	    /** Written for a due that has no rate to work from. */
253	    private static final String NO_RATE = "n/a";
254	
255	    /** The name a claim's period number takes when its date falls in no period. */
256	    private static final String NO_PERIOD = "X";
257	
258	    private final ClaimRepository claims;
259	    private final ClaimLogRepository logs;
260	    private final PersonRepository people;
261	    private final RateService rates;
262	    private final PersonGradeService grades;
263	    private final SheetService sheets;
264	    private final PeriodRepository periods;
265	    private final SettingService settings;
266	    private final Audit audit;
267	
268	    public ClaimService(ClaimRepository claims, ClaimLogRepository logs, PersonRepository people, RateService rates,
269	            PersonGradeService grades, SheetService sheets, PeriodRepository periods, SettingService settings, Audit audit) {
270	        this.periods = periods;
271	        this.settings = settings;
272	        this.claims = claims;
273	        this.logs = logs;
274	        this.people = people;
275	        this.rates = rates;
276	        this.grades = grades;
277	        this.sheets = sheets;
278	        this.audit = audit;
279	    }
280	
281	    /** The sheet's claims, newest first. */
282	    public List<Claim> list(String sheetId) {
283	        return claims.findBySheetIdOrderByListedDesc(sheetId);
284	    }
285	
286	    /** Add a claim for a person; a missing date takes the sheet's today. Its due-by is fixed now: its
287	     *  date plus the terms in force on that date for the person's grade then. A negative amount is a
288	     *  correction and must name a SETTLED claim of the person it corrects. */
289	    @Transactional
290	    public Claim add(String sheetId, String user, Long personId, BigDecimal amount, LocalDate date, String note,
291	            String corrects) {
292	        Person person = person(sheetId, personId);
293	        corrects = numberOf(corrects);
294	        LocalDate on = date != null ? date : sheets.today(sheetId);
295	        refuseClosed(sheetId, on);
296	        refuseRetired(person, on);
297	        refuseBadCorrection(sheetId, personId, amount, corrects);
298	        LocalDate dueBy = on.plusDays(settings.termsFor(sheetId, grades.gradeOn(personId, on), on));
299	        Claim added = claims.saveAndFlush(new Claim(sheetId, personId, scaled(amount), on, dueBy, noteOf(note),
300	                corrects));
301	        log(sheetId, user, person, added);
302	        record("CLAIM_ADDED", sheetId, user, person, added);
303	        return added;
304	    }
305	
306	    /** Change a DRAFT claim's amount, date and note; a missing date takes the sheet's today. Any
307	     *  other claim is refused: an OPEN one is changed by voiding it and adding a new one. */
308	    @Transactional
309	    public Claim update(String sheetId, String user, Long personId, Long id, BigDecimal amount, LocalDate date,
310	            String note, String corrects) {
311	        Person person = person(sheetId, personId);
312	        corrects = numberOf(corrects);
313	        Claim claim = claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
314	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
315	        if (claim.getStatus() != ClaimStatus.DRAFT) {
316	            throw new ClaimNotEditableException(claim.getStatus());
317	        }
318	        LocalDate on = date != null ? date : sheets.today(sheetId);
319	        refuseClosed(sheetId, claim.getDate());
320	        refuseClosed(sheetId, on);
321	        refuseRetired(person, on);
322	        refuseBadCorrection(sheetId, personId, amount, corrects);
323	        claim.setAmount(scaled(amount));
324	        claim.setCorrects(corrects);
325	        claim.setDate(on);
326	        claim.setNote(noteOf(note));
327	        Claim saved = claims.saveAndFlush(claim);
328	        record("CLAIM_EDITED", sheetId, user, person, saved);
329	        return saved;
330	    }
331	
332	    /** Move a claim to a new status; a change its status does not allow is refused, as is the user
333	     *  who opened a claim settling it. A clerk settling a claim whose due is above the clerk limit
334	     *  leaves it PENDING a steward's approval instead. */
335	    @Transactional
336	    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
337	        Person person = person(sheetId, personId);
338	        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
339	        // read below is its latest state.
340	        if (to == ClaimStatus.OPEN) {
341	            sheets.lock(sheetId);
342	        }
343	        Claim claim = claim(sheetId, personId, id);
344	        refuseClosed(sheetId, claim.getDate());
345	        if (!claim.getStatus().canMoveTo(to)) {
346	            throw new StatusChangeRefusedException(claim.getStatus(), to);
347	        }
348	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
349	            throw new OwnClaimSettleRefusedException(user);
350	        }
351	        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
352	        // gathered by then.
353	        BigDecimal due = to == ClaimStatus.SETTLED ? dueOf(sheetId, person, claim) : null;
354	        if (to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, due)) {
355	            to = ClaimStatus.PENDING;
356	        }
357	        claim.setStatus(to);
358	        if (to == ClaimStatus.OPEN) {
359	            claim.setNumber(nextNumber(sheetId, claim.getDate()));
360	            claim.setOpenedBy(user);
361	        } else if (to == ClaimStatus.SETTLED) {
362	            claim.setSettledDue(due);
363	        }
364	        Claim saved = claims.saveAndFlush(claim);
365	        log(sheetId, user, person, saved);
366	        String event = switch (to) {
367	            case OPEN -> "CLAIM_OPENED";
368	            case PENDING -> "CLAIM_PENDING";
369	            case SETTLED -> "CLAIM_SETTLED";
370	            case VOID -> "CLAIM_VOIDED";
371	            case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
372	        };
373	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
374	        if (to == ClaimStatus.SETTLED) {
375	            line += " due=" + settledDueText(saved);
376	        }
377	        audit.recordOnCommit(line);
378	        return saved;
379	    }
380	
381	    /** A steward approves a PENDING claim: it is SETTLED, its due frozen at this moment. Anyone else,
382	     *  the user who opened it, or a claim that is not PENDING, is refused. */
383	    @Transactional
384	    public Claim approve(String sheetId, String user, Long personId, Long id) {
385	        Person person = person(sheetId, personId);
386	        Claim claim = pending(sheetId, user, personId, id, ClaimStatus.SETTLED);
387	        if (user.equals(claim.getOpenedBy())) {
388	            throw new OwnClaimSettleRefusedException(user);
389	        }
390	        claim.setSettledDue(dueOf(sheetId, person, claim));
391	        claim.setStatus(ClaimStatus.SETTLED);
392	        Claim saved = claims.saveAndFlush(claim);
393	        log(sheetId, user, person, saved);
394	        audit.recordOnCommit(line("CLAIM_APPROVED", sheetId, user, person, saved, saved.getNumber())
395	                + " due=" + settledDueText(saved));
396	        return saved;
397	    }
398	
399	    /** A steward rejects a PENDING claim with a reason: it is OPEN again, bound again by the person's
400	     *  last statement if that statement bound it. Anyone else, or a claim that is not PENDING, is
401	     *  refused. */
402	    @Transactional
403	    public Claim reject(String sheetId, String user, Long personId, Long id, String reason) {
404	        Person person = person(sheetId, personId);
405	        Claim claim = pending(sheetId, user, personId, id, ClaimStatus.OPEN);
406	        claim.setStatus(ClaimStatus.OPEN);
407	        Claim saved = claims.saveAndFlush(claim);
408	        log(sheetId, user, person, saved);
409	        audit.recordOnCommit(line("CLAIM_REJECTED", sheetId, user, person, saved, saved.getNumber())
410	                + " reason=" + reason.trim());
411	        return saved;
412	    }
413	
414	    /** A steward re-settles a SETTLED claim: its settled due is frozen again at the figure it would
415	     *  have today as an OPEN claim bound by no statement (today's rates, grades, floor and late
416	     *  charge), and its status log gains a SETTLED line. Anyone else, a claim that is not SETTLED, or
417	     *  one dated in a closed period, is refused. */
418	    @Transactional
419	    public Claim resettle(String sheetId, String user, Long personId, Long id) {
420	        Person person = person(sheetId, personId);
421	        Claim claim = claim(sheetId, personId, id);
422	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
423	            throw new ResettleRefusedException(user);
424	        }
425	        if (claim.getStatus() != ClaimStatus.SETTLED) {
426	            throw new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED);
427	        }
428	        refuseClosed(sheetId, claim.getDate());
429	        String old = settledDueText(claim);
430	        BigDecimal figure = liveFigureOf(sheetId, person, claim);
431	        claim.setSettledDue(figure == null ? null : figure.add(lateChargeOf(sheetId, claim, figure, true)));
432	        Claim saved = claims.saveAndFlush(claim);
433	        log(sheetId, user, person, saved);
434	        audit.recordOnCommit(line("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber())
435	                + " old=" + old + " new=" + settledDueText(saved));
436	        return saved;
437	    }
438	
439	    /** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
440	     *  number and date, loses any figure a statement bound it to (live again until its new person's
441	     *  next statement), and is listed as its new person's newest claim. Anyone else, a SETTLED or VOID
442	     *  claim, a correction (it names a claim of its own person), a claim dated in a closed period, or
443	     *  a move to the same person or to one retired before the claim's date, is refused. */
444	    @Transactional
445	    public Claim reassign(String sheetId, String user, Long personId, Long id, Long toPersonId) {
446	        Person from = person(sheetId, personId);
447	        Person to = person(sheetId, toPersonId);
448	        Claim claim = claim(sheetId, personId, id);
449	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
450	            throw new ReassignRefusedException(user);
451	        }
452	        if (!claim.getStatus().canReassign()) {
453	            throw new MoveRefusedException("A " + claim.getStatus() + " claim cannot move to another person");
454	        }
455	        if (from.getId().equals(to.getId())) {
456	            throw new MoveRefusedException("The claim is already " + to.getName() + "'s");
457	        }
458	        if (claim.isCorrection()) {
459	            throw new MoveRefusedException("A correction stays with the person whose claim it corrects");
460	        }
461	        refuseClosed(sheetId, claim.getDate());
462	        refuseRetired(to, claim.getDate());
463	        claim.setPersonId(to.getId());
464	        claim.unbind();
465	        claims.saveAndFlush(claim);
466	        claims.relist(claim.getId());
467	        Claim saved = claim(sheetId, to.getId(), id);
468	        audit.recordOnCommit(line("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber())
469	                + " from=" + from.getName() + " to=" + to.getName());
470	        return saved;
471	    }
472	
473	    /** A claim's status log, oldest first: one line per status it has had. */
474	    public List<String> logOf(Long claimId) {
475	        return logs.findByClaimIdOrderByIdAsc(claimId).stream().map(ClaimLogEntry::text).toList();
476	    }
477	
478	    /** The status logs of the sheet's claims by claim id, each oldest first. */
479	    public Map<Long, List<String>> logsOf(String sheetId) {
480	        return logs.findBySheetIdOrderByIdAsc(sheetId).stream().collect(Collectors.groupingBy(
481	                ClaimLogEntry::getClaimId, Collectors.mapping(ClaimLogEntry::text, Collectors.toList())));
482	    }
483	
484	    /** Log the status a claim has just moved to (or been added in): by whom, on the sheet's today, and
485	     *  its due as it is now. */
486	    private void log(String sheetId, String user, Person person, Claim claim) {
487	        BigDecimal due = dueOf(sheetId, person, claim);
488	        logs.save(new ClaimLogEntry(sheetId, claim.getId(), claim.getStatus(), user, sheets.today(sheetId),
489	                due != null ? due.toPlainString() : NO_RATE));
490	    }
491	
492	    /** The PENDING claim a steward approves or rejects; refused when it is not PENDING, dated in a
493	     *  closed period, or the user is not a steward. */
494	    private Claim pending(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
495	        Claim claim = claim(sheetId, personId, id);
496	        refuseClosed(sheetId, claim.getDate());
497	        if (claim.getStatus() != ClaimStatus.PENDING) {
498	            throw new StatusChangeRefusedException(claim.getStatus(), to);
499	        }
500	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
501	            throw new ApprovalRefusedException(user);
502	        }
503	        return claim;
504	    }
505	
506	    private Claim claim(String sheetId, Long personId, Long id) {
507	        return claims.findByIdAndSheetIdAndPersonId(id, sheetId, personId)
508	                .orElseThrow(() -> new NoSuchElementException("No claim " + id + " for person " + personId));
509	    }
510	
511	    private static String settledDueText(Claim claim) {
512	        return claim.getSettledDue() != null ? claim.getSettledDue().toPlainString() : NO_RATE;
513	    }
514	
515	    /** The number a claim opened now takes: under period numbering (set, and the sheet's today on or
516	     *  after it) the next within the period its date falls in, <period>-<n>, or X-<n> when it falls
517	     *  in none; otherwise the sheet's next sheet-wide number. Taken with the sheet locked. */
518	    private String nextNumber(String sheetId, LocalDate date) {
519	        LocalDate from = settings.periodNumberingFrom(sheetId);
520	        if (from == null || sheets.today(sheetId).isBefore(from)) {
521	            return String.valueOf(sheets.nextClaimNumber(sheetId));
522	        }
523	        String prefix = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
524	                .filter(period -> period.contains(date))
525	                .findFirst().map(Period::getName).orElse(NO_PERIOD) + "-";
526	        long last = claims.numbers(sheetId).stream()
527	                .filter(number -> number.startsWith(prefix))
528	                .map(number -> number.substring(prefix.length()))
529	                .filter(n -> n.matches("\\d{1,18}"))
530	                .mapToLong(Long::parseLong)
531	                .max().orElse(0);
532	        return prefix + (last + 1);
533	    }
534	
535	    /** The figure a claim shows: the due fixed when it was settled, else (unless it is PENDING, which
536	     *  no statement binds) the figure its person's last statement bound it to, else its due at the
537	     *  person's grade rate; null when it has none. */
538	    public BigDecimal figureOf(String sheetId, Person person, Claim claim) {
539	        if (claim.getSettledDue() != null) {
540	            return claim.getSettledDue();
541	        }
542	        return claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue() : liveFigureOf(sheetId, person, claim);
543	    }
544	
545	    /** The due a claim shows: its figure plus its late charge; null when it has no figure. */
546	    public BigDecimal dueOf(String sheetId, Person person, Claim claim) {
547	        BigDecimal figure = figureOf(sheetId, person, claim);
548	        return figure == null ? null : figure.add(lateChargeOf(sheetId, claim, figure, claim.getStatus().isOpen()));
549	    }
550	
551	    /** The late charge on a claim with a figure: none unless it is OPEN or PENDING and overdue (its due-by is
552	     *  before the sheet's today) or a correction, else the late percent of the figure for every full 30 days
553	     *  it is overdue (the late percent in force on the claim's date), rounded to two decimals as the claim's date decides (see roundingOf). Never bound by a statement: it follows the
554	     *  sheet's today. Whether the claim counts as open is given, so a re-settle can charge a SETTLED
555	     *  claim as if it were still OPEN. */
556	    private BigDecimal lateChargeOf(String sheetId, Claim claim, BigDecimal figure, boolean open) {
557	        BigDecimal none = BigDecimal.ZERO.setScale(2);
558	        if (!open || claim.isCorrection()) {
559	            return none;
560	        }
561	        long days = ChronoUnit.DAYS.between(claim.getDueBy(), sheets.today(sheetId));
562	        if (days < 30) {
563	            return none;
564	        }
565	        return figure.multiply(settings.latePct(sheetId, claim.getDate())).multiply(BigDecimal.valueOf(days / 30))
566	                .movePointLeft(2).setScale(2, roundingOf(sheetId, claim));
567	    }
568	
569	    /** The due on a claim at the rate in force on the claim's date for the person's grade in force
570	     *  on the claim's date: amount times rate
571	     *  divided by 100, rounded to two decimals as the claim's date decides (see roundingOf), and at least the sheet's floor in force on its date unless it
572	     *  is a correction; null when no rate applies. */
573	    private BigDecimal liveFigureOf(String sheetId, Person person, Claim claim) {
574	        BigDecimal amount = claim.getAmount();
575	        RoundingMode rounding = roundingOf(sheetId, claim);
576	        return rates.rateOn(sheetId, grades.gradeOn(person.getId(), claim.getDate()), claim.getDate())
577	                .map(Rate::getRate)
578	                .map(rate -> amount.multiply(rate).movePointLeft(2).setScale(2, rounding))
579	                .map(due -> claim.isCorrection() ? due : due.max(settings.floor(sheetId, claim.getDate())))
580	                .orElse(null);
581	    }
582	
583	    /** The date a claim's live figures round by: its own, or for a correction the date of the claim
584	     *  it corrects. */
585	    public LocalDate roundsBy(String sheetId, Claim claim) {
586	        if (!claim.isCorrection() || claim.getCorrects() == null) {
587	            return claim.getDate();
588	        }
589	        return claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects())
590	                .map(Claim::getDate).orElse(claim.getDate());
591	    }
592	
593	    /** How a claim's live figures round: by the sheet's policy date against the date it rounds by. */
594	    private RoundingMode roundingOf(String sheetId, Claim claim) {
595	        return settings.roundingOn(sheetId, roundsBy(sheetId, claim));
596	    }
597	
598	    /** Whether a clerk is settling a claim whose due is above the sheet's clerk limit; a due of n/a
599	     *  is within any limit, and a steward settles anything. */
600	    private boolean overClerkLimit(String sheetId, String user, BigDecimal due) {
601	        BigDecimal limit = settings.clerkLimit(sheetId);
602	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
603	            return false;
604	        }
605	        return settings.roleOf(sheetId, user) == Role.CLERK;
606	    }
607	
608	    /** A negative amount (a correction) must name the number of a SETTLED claim of the same person;
609	     *  any other amount names none. */
610	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
611	        if (amount.signum() >= 0) {
612	            if (corrects != null) {
613	                throw new CorrectionRefusedException("Only a negative amount corrects a claim");
614	            }
615	            return;
616	        }
617	        if (corrects == null) {
618	            throw new CorrectionRefusedException("A negative amount must name the claim it corrects");
619	        }
620	        boolean settled = claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
621	                .map(c -> c.getStatus() == ClaimStatus.SETTLED).orElse(false);
622	        if (!settled) {
623	            throw new CorrectionRefusedException("No SETTLED claim " + corrects + " of this person to correct");
624	        }
625	    }
626	
627	    /** A claim dated inside a closed period cannot be added, edited, opened, settled or voided. */
628	    private void refuseClosed(String sheetId, LocalDate date) {
629	        if (periods.closedOn(sheetId, date)) {
630	            throw new PeriodClosedException("A claim dated " + date + " falls in a closed period");
631	        }
632	    }
633	
634	    /** A claim dated after its person's retirement date cannot be added or moved there. */
635	    private static void refuseRetired(Person person, LocalDate date) {
636	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
637	            throw new PersonRetiredException(person.getName(), person.getRetiredFrom(), date);
638	        }
639	    }
640	
641	    private Person person(String sheetId, Long personId) {
642	        return people.findByIdAndSheetId(personId, sheetId)
643	                .orElseThrow(() -> new NoSuchElementException("No person " + personId + " on sheet " + sheetId));
644	    }
645	
646	    private void record(String event, String sheetId, String user, Person person, Claim claim) {
647	        record(event, sheetId, user, person, claim, claim.getNumber());
648	    }
649	
650	    /** One audit line about a claim; a claim with a number carries it at the end. */
651	    private void record(String event, String sheetId, String user, Person person, Claim claim, String number) {
652	        audit.recordOnCommit(line(event, sheetId, user, person, claim, number));
653	    }
654	
655	    private static String line(String event, String sheetId, String user, Person person, Claim claim, String number) {
656	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName()
657	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
658	                + (number != null ? " number=" + number : "");
659	    }
660	
661	    private static BigDecimal scaled(BigDecimal amount) {
662	        return amount.setScale(2, RoundingMode.UNNECESSARY);
663	    }
664	
665	    /** A claim number as typed: trimmed, null when blank. */
666	    private static String numberOf(String number) {
667	        return number == null || number.isBlank() ? null : number.trim();
668	    }
669	
670	    private static String noteOf(String note) {
671	        return note == null ? "" : note.trim();
672	    }
673	}
674	package net.officefloor.hq.app.claim;
675	
676	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; an OPEN claim a clerk settles above
677	 *  the clerk limit is PENDING until a steward approves it (SETTLED) or rejects it (OPEN again); a
678	 *  DRAFT, OPEN or PENDING claim can be VOID. */
679	public enum ClaimStatus {
680	    DRAFT, OPEN, PENDING, SETTLED, VOID;
681	
682	    /** Whether the claim counts toward what is claimed and due. */
683	    public boolean counts() {
684	        return this == OPEN || this == PENDING || this == SETTLED;
685	    }
686	
687	    /** Whether the claim is open: OPEN, or PENDING an approval. */
688	    public boolean isOpen() {
689	        return this == OPEN || this == PENDING;
690	    }
691	
692	    /** Whether a claim in this status may be moved to another person: a SETTLED or VOID one cannot. */
693	    public boolean canReassign() {
694	        return this == DRAFT || this == OPEN || this == PENDING;
695	    }
696	
697	    /** Whether a claim in this status may be opened, settled or voided to the given one; a PENDING
698	     *  claim leaves PENDING only by being approved, rejected or voided. */
699	    public boolean canMoveTo(ClaimStatus next) {
700	        return switch (next) {
701	            case OPEN -> this == DRAFT;
702	            case SETTLED -> this == OPEN;
703	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
704	            case PENDING, DRAFT -> false;
705	        };
706	    }
707	}
