          <button type="button" data-testid="claim-approve" [attr.aria-label]="'Approve claim ' + c.id" (click)="act(c, 'approve')">
            Approve
          </button>
          <label [for]="'claim-reject-reason-' + c.id">Reject reason</label>
          <input
