    @Transactional
    public Period close(String sheetId, String user, String name) {
        sheets.lock(sheetId);
        Period period = periods.findBySheetIdAndName(sheetId, name)
                .orElseThrow(() -> new NoSuchElementException("No period " + name + " on sheet " + sheetId));
        if (period.isClosed()) {
            throw new PeriodClosedException("The period " + name + " is already closed");
        }
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, List<PersonHold>> holds = personService.holds(sheetId);
        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
        byId.keySet().forEach(id -> personTotals.put(id, BigDecimal.ZERO.setScale(2)));
        for (Claim claim : claims.findBySheetIdOrderByListedDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !claim.countsLive(holds.getOrDefault(person.getId(), List.of()))
                    || !period.contains(claim.getDate())) {
                continue;
            }
            BigDecimal due = claimService.dueOf(sheetId, person, claim);
            if (due != null) {
                personTotals.merge(person.getId(), due, BigDecimal::add);
            }
        }
        BigDecimal total = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
        period.close(total, personTotals);
        Period saved = periods.saveAndFlush(period);
        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + name
                + " total=" + total.toPlainString());
        return saved;
    }
    private final ClaimListOrder order;
    private final ClaimService service;
    private final RollupService rollups;

    public BulkSettleService(ClaimListOrder order, ClaimService service, RollupService rollups) {
        this.order = order;
        this.service = service;
        this.rollups = rollups;
    }

    /** Settle each selected claim that can be settled, in list order (people in the order they were
     *  added, each person's claims newest first), by exactly the rules of settling one: a clerk's
     *  claim above the clerk limit goes PENDING and counts as settled. Each that cannot, or is not
     *  on the sheet, is refused and left as it is. Each claim is settled on its own, so a refused
     *  one writes nothing. */
    public Result settle(String sheetId, String user, Set<Long> ids) {
        List<Claim> settled = new ArrayList<>();
        for (Claim claim : order.selected(sheetId, ids)) {
            try {
                settled.add(rollups.track(sheetId, user, () -> service.changeStatus(sheetId, user,
                        claim.getPersonId(), claim.getId(), ClaimStatus.SETTLED)));
            } catch (StatusChangeRefusedException | OwnClaimSettleRefusedException | PeriodClosedException
                    | NoSuchElementException refused) {
                // Left as it is: its change rolled back with its own transaction.
            }
        }
        return new Result(settled, ids.size() - settled.size());
    }
}
-- A hold is dated: it runs from its from-date to its to-date (none: open-ended), and a person may
-- have several holds over time. Only a person's OPEN claims dated within one of their holds, and
-- not bound by a statement, are left out of the live totals. A person on hold before holds were
-- dated keeps a hold from the beginning of time with no end.
CREATE TABLE person_hold (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    from_date DATE NOT NULL,
    to_date DATE
);
CREATE INDEX person_hold_sheet ON person_hold (sheet_id, person_id);
INSERT INTO person_hold (sheet_id, person_id, from_date, to_date)
    SELECT sheet_id, id, DATE '0001-01-01', NULL FROM person WHERE held = TRUE;
ALTER TABLE person DROP COLUMN held;
